function generateBreadcrumbs(){let e=document.getElementById("breadcrumbs");if(!e)return;e.innerHTML="";let t=window.location.pathname.split("/").filter(e=>e.length>0),n="",r=document.querySelector("h1"),a=r?r.textContent:document.title;t=t.filter(e=>"index.php"!==e);let l=window.location.search?window.location.search.substring(1):null;t.forEach((r,i)=>{n+="/"+r;let o=i===t.length-1,c=capitalizeFirstLetterOfEachWord(r.replace(/-/g," ")),h=document.createElement("li");if(o)h.textContent=c,"mmenu"===r?h.textContent=`Home > ${a}`:r.endsWith(".php")&&(h.textContent=a);else{let p=document.createElement("a");p.href=n,0===i&&(p.href="/mmenu.php"),l&&"inactivity"!==l&&(p.href+=`?${l}`),p.textContent="mmenu"===r?"Home":c,h.appendChild(p)}e.appendChild(h)})}function capitalizeFirstLetterOfEachWord(e){return e.replace(/\b\w/g,e=>e.toUpperCase())}window.onload=generateBreadcrumbs;